import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        long result = 1;

        if (k == 0) {
            for (int i = 1; i < p; ++i)
                result = (result * p) % MOD;
            System.out.println(result);
            return;
        }

        if (k == 1) {
            for (int i = 0; i < p; ++i)
                result = (result * p) % MOD;
            System.out.println(result);
            return;
        }

        long[] power = new long[p + 1];
        power[0] = 1;
        for (int i = 1; i <= p; ++i)
            power[i] = (power[i - 1] * k) % p;

        boolean[] visited = new boolean[p];
        for (int i = 1; i < p; ++i) {
            if (!visited[i]) {
                int j = i, length = 0;
                do {
                    visited[j] = true;
                    ++length;
                    j = (int)((long)k * j % p);
                } while (!visited[j]);

                if (power[length] == 1)
                    result = (result * p) % MOD;
            }
        }

        System.out.println(result);
    }
}
